<?php require_once __DIR__.'/../includes/bootstrap.php';require_admin();$title='Management Audit Log';$rows=$pdo->query('SELECT a.*,u.username FROM admin_audit_log a LEFT JOIN users u ON u.user_id=a.user_id ORDER BY a.created_at DESC LIMIT 150')->fetchAll();require __DIR__.'/../includes/header.php';?><div class="admin-layout"><aside class="admin-side"><strong>Management</strong><a href="/admin/dashboard.php">Dashboard</a><a href="/admin/settings.php">Settings</a><a class="active" href="/admin/audit.php">Audit log</a><a href="/admin/system.php">System health</a></aside><section class="admin-main"><div class="section-head"><div><span class="eyebrow">ACCOUNTABILITY</span><h1>Management audit log</h1><p>Important management actions are recorded here for operational accountability.</p></div></div><div class="table-wrap"><table><thead><tr><th>Date</th><th>User</th><th>Action</th><th>Details</th><th>IP</th></tr></thead><tbody><?php foreach($rows as $r):?><tr><td><?=e($r['created_at'])?></td><td><?=e($r['username']??'System')?></td><td><strong><?=e($r['action'])?></strong></td><td><?=e($r['details']??'')?></td><td><?=e($r['ip_address']??'')?></td></tr><?php endforeach;?></tbody></table></div></section></div><?php require __DIR__.'/../includes/footer.php';?>
